        "filename": "styles.css.ts",
        "code": "import { style, styleVariants } from \"@vanilla-extract/css\";\n\nexport const button = style({\n  display: \"inline-flex\",\n  alignItems: \"center\",\n  justifyContent: \"center\",\n  gap: \"var(--space-2)\",\n  border: \"1px solid transparent\",\n  borderRadius: \"var(--radius)\",\n  fontWeight: \"var(--weight-medium)\",\n  lineHeight: 1,\n  whiteSpace: \"nowrap\",\n  cursor: \"pointer\",\n  transition:\n    \"background-color var(--duration-fast), color var(--duration-fast), border-color var(--duration-fast), transform 80ms ease-out, filter 80ms\",\n  userSelect: \"none\",\n  WebkitTapHighlightColor: \"transparent\",\n\n  selectors: {\n    \"&:disabled\": {\n      opacity: \"var(--opacity-disabled)\",\n      pointerEvents: \"none\",\n    },\n    \"&:focus-visible\": {\n      outline: \"var(--border-width-strong) solid var(--ring)\",\n      outlineOffset: \"2px\",\n    },\n    \"&:active:not(:disabled)\": {\n      transform: \"scale(0.97)\",\n      transitionDuration: \"40ms\",\n    },\n  },\n\n  \"@media\": {\n    \"(prefers-reduced-motion: reduce)\": {\n      transition: \"none\",\n    },\n  },\n});\n\nexport const sizes = styleVariants({\n  sm: {\n    height: \"var(--control-sm)\",\n    padding: \"0 var(--space-3)\",\n    fontSize: \"var(--text-sm)\",\n    \"@media\": {\n      \"(hover: none) and (pointer: coarse)\": {\n        height: \"2.25rem\",\n      },\n    },\n  },\n  md: {\n    height: \"var(--control-md)\",\n    padding: \"0 var(--space-4)\",\n    fontSize: \"var(--text-sm)\",\n    \"@media\": {\n      \"(hover: none) and (pointer: coarse)\": {\n        height: \"2.75rem\",\n      },\n    },\n  },\n  lg: {\n    height: \"var(--control-lg)\",\n    padding: \"0 var(--space-5)\",\n    fontSize: \"var(--text-base)\",\n  },\n});\n\nexport const variants = styleVariants({\n  primary: {\n    backgroundColor: \"var(--primary)\",\n    color: \"var(--primary-foreground)\",\n    selectors: {\n      \"&:hover\": {\n        backgroundColor: \"var(--primary-hover)\",\n      },\n    },\n  },\n  secondary: {\n    backgroundColor: \"var(--background-muted)\",\n    color: \"var(--foreground)\",\n    borderColor: \"var(--border)\",\n    selectors: {\n      \"&:hover\": {\n        backgroundColor: \"var(--background-subtle)\",\n      },\n    },\n  },\n  ghost: {\n    backgroundColor: \"transparent\",\n    color: \"var(--foreground)\",\n    selectors: {\n      \"&:hover\": {\n        backgroundColor: \"var(--background-muted)\",\n      },\n    },\n  },\n  danger: {\n    backgroundColor: \"var(--danger)\",\n    color: \"var(--danger-foreground)\",\n    selectors: {\n      \"&:hover\": { backgroundColor: \"var(--danger-hover)\" },\n    },\n  },\n  link: {\n    backgroundColor: \"transparent\",\n    color: \"var(--foreground)\",\n    borderColor: \"transparent\",\n    height: \"auto\",\n    padding: 0,\n    textUnderlineOffset: \"3px\",\n    selectors: {\n      \"&:hover\": {\n        textDecoration: \"underline\",\n      },\n      \"&:active:not(:disabled)\": {\n        transform: \"none\",\n        filter: \"none\",\n        color: \"var(--foreground-muted)\",\n      },\n    },\n  },\n});\n",
