        "code": "import { globalStyle, style } from \"@vanilla-extract/css\";\n\nexport const input = style({\n  display: \"block\",\n  width: \"100%\",\n  height: \"var(--control-md)\",\n  padding: \"0 var(--space-3)\",\n  background: \"var(--background)\",\n  color: \"var(--foreground)\",\n  border: \"1px solid var(--border)\",\n  borderRadius: \"var(--radius)\",\n  fontFamily: \"inherit\",\n  fontSize: \"var(--text-sm)\",\n  lineHeight: 1,\n  transition: \"border-color var(--duration-fast), box-shadow var(--duration-fast)\",\n  WebkitTapHighlightColor: \"transparent\",\n\n  selectors: {\n    \"&::placeholder\": {\n      color: \"var(--foreground-subtle)\",\n    },\n    \"&:hover:not(:disabled):not(:focus)\": {\n      borderColor: \"var(--border-strong)\",\n    },\n    \"&:focus\": {\n      outline: \"none\",\n      borderColor: \"var(--foreground)\",\n      boxShadow: \"0 0 0 1px var(--primary)\",\n    },\n    \"&:disabled\": {\n      opacity: \"var(--opacity-disabled)\",\n      cursor: \"not-allowed\",\n      background: \"var(--background-subtle)\",\n    },\n    \"&:read-only\": {\n      background: \"var(--background-subtle)\",\n    },\n    '&[type=\"number\"]::-webkit-outer-spin-button': {\n      WebkitAppearance: \"none\",\n      margin: 0,\n    },\n    '&[type=\"number\"]::-webkit-inner-spin-button': {\n      WebkitAppearance: \"none\",\n      margin: 0,\n    },\n    '&[type=\"number\"]': {\n      MozAppearance: \"textfield\",\n    },\n    '&[aria-invalid=\"true\"]': {\n      borderColor: \"var(--danger)\",\n    },\n    '&[aria-invalid=\"true\"]:focus': {\n      boxShadow: \"0 0 0 1px var(--danger)\",\n    },\n    \"&[data-in-group]\": {\n      flex: \"1 1 auto\",\n      minWidth: 0,\n      height: \"auto\",\n      padding: 0,\n      background: \"transparent\",\n      border: \"none\",\n      borderRadius: 0,\n      boxShadow: \"none\",\n    },\n    \"&[data-in-group]:focus, &[data-in-group]:hover\": {\n      border: \"none\",\n      boxShadow: \"none\",\n      outline: \"none\",\n    },\n    \"&[data-in-group]:disabled\": {\n      background: \"transparent\",\n    },\n  },\n\n  \"@media\": {\n    \"(hover: none) and (pointer: coarse)\": {\n      height: \"2.75rem\",\n      fontSize: \"var(--text-base)\",\n    },\n  },\n});\n\nexport const inputWrap = style({\n  position: \"relative\",\n  width: \"100%\",\n  display: \"block\",\n\n  selectors: {\n    \"&[data-in-group]\": {\n      flex: \"1 1 auto\",\n      minWidth: 0,\n    },\n  },\n});\n\nexport const withPrefix = style({ paddingLeft: \"var(--space-10)\" });\nexport const withSuffix = style({ paddingRight: \"var(--space-10)\" });\n\nexport const affix = style({\n  position: \"absolute\",\n  top: \"50%\",\n  transform: \"translateY(-50%)\",\n  display: \"inline-flex\",\n  alignItems: \"center\",\n  justifyContent: \"center\",\n  color: \"var(--foreground-muted)\",\n  pointerEvents: \"none\",\n});\n\n// vanilla-extract 의 selectors 키는 universal/element descendant (& > *) 도 허용 안 함.\n// 자식 요소에 룰 적용하려면 globalStyle 로 빼야 함.\nglobalStyle(`${affix} > *`, {\n  pointerEvents: \"auto\",\n});\n\nexport const affixPrefix = style({ left: \"var(--space-3)\" });\nexport const affixSuffix = style({ right: \"var(--space-1)\" });\n\nexport const toggle = style({\n  display: \"inline-flex\",\n  alignItems: \"center\",\n  justifyContent: \"center\",\n  width: \"2rem\",\n  height: \"2rem\",\n  padding: 0,\n  background: \"transparent\",\n  border: \"none\",\n  borderRadius: \"calc(var(--radius) - 2px)\",\n  color: \"var(--foreground-muted)\",\n  cursor: \"pointer\",\n  transition: \"color var(--duration-fast), background-color var(--duration-fast)\",\n  WebkitTapHighlightColor: \"transparent\",\n\n  selectors: {\n    \"&:hover\": {\n      color: \"var(--foreground)\",\n      background: \"var(--background-muted)\",\n    },\n    \"&:focus-visible\": {\n      outline: \"var(--border-width-strong) solid var(--ring)\",\n      outlineOffset: \"2px\",\n    },\n  },\n});\n\nexport const group = style({\n  display: \"flex\",\n  alignItems: \"center\",\n  width: \"100%\",\n  minHeight: \"var(--control-md)\",\n  padding: \"0 var(--space-2)\",\n  gap: \"var(--space-2)\",\n  background: \"var(--background)\",\n  color: \"var(--foreground)\",\n  border: \"1px solid var(--border)\",\n  borderRadius: \"var(--radius)\",\n  transition: \"border-color var(--duration-fast), box-shadow var(--duration-fast)\",\n  cursor: \"text\",\n  WebkitTapHighlightColor: \"transparent\",\n\n  selectors: {\n    \"&:hover:not([data-disabled]):not(:focus-within)\": {\n      borderColor: \"var(--border-strong)\",\n    },\n    \"&:focus-within\": {\n      borderColor: \"var(--foreground)\",\n      boxShadow: \"0 0 0 1px var(--primary)\",\n    },\n    '&[aria-invalid=\"true\"]': {\n      borderColor: \"var(--danger)\",\n    },\n    '&[aria-invalid=\"true\"]:focus-within': {\n      boxShadow: \"0 0 0 1px var(--danger)\",\n    },\n    \"&[data-disabled]\": {\n      opacity: \"var(--opacity-disabled)\",\n      cursor: \"not-allowed\",\n      background: \"var(--background-subtle)\",\n    },\n  },\n\n  \"@media\": {\n    \"(hover: none) and (pointer: coarse)\": {\n      minHeight: \"2.75rem\",\n    },\n  },\n});\n\nexport const adornment = style({\n  display: \"inline-flex\",\n  alignItems: \"center\",\n  justifyContent: \"center\",\n  flex: \"0 0 auto\",\n  color: \"var(--foreground-muted)\",\n  padding: \"0 var(--space-1)\",\n\n  selectors: {\n    \"&[data-interactive]\": {\n      padding: 0,\n    },\n  },\n});\n",
